from pathlib import Path
C=Path('work/deliverables/undertow/elements')
def add(n,s):p=C/n/'element.css';p.write_text(p.read_text()+'\n'+s)
p=C/'card/element.css';p.write_text(p.read_text().replace('.parts:has(.fig) {grid-template-rows:', '.parts:has(.fig):has(.kick) {grid-template-rows:'))
r='.spark[data-el="undertow-sparkline"]';s=r+' {anchor-scope:all;} '+r+':is(.card .parts > *, .stat .parts > *) {width:100%;height:64px;min-height:64px;} '+r+'.bars.up > span {background:var(--good);} '+r+'.bars.down > span {background:var(--bad);} '+r+':not(.bars) {--undertow-spark-color:var(--a1);} '+r+'.up:not(.bars) {--undertow-spark-color:var(--good);} '+r+'.down:not(.bars) {--undertow-spark-color:var(--bad);} '+r+':not(.bars) > span {position:static;height:0;min-height:0;background:none;border:0;margin-bottom:calc(var(--v)/var(--max)*(100cqh - var(--gap)));anchor-name:var(--undertow-spark-self);} '+r+':not(.bars) > span::before,'+r+':not(.bars) > span::after {content:"";position:absolute;left:anchor(var(--undertow-spark-prev) center);right:anchor(var(--undertow-spark-self) center);height:auto;} '+r+':not(.bars) > span::before {top:calc(anchor(var(--undertow-spark-prev) bottom) - 1px);bottom:calc(anchor(var(--undertow-spark-self) bottom) - 1px);background:linear-gradient(to top right,transparent calc(50% - 1px),var(--undertow-spark-color) calc(50% - 1px),var(--undertow-spark-color) calc(50% + 1px),transparent calc(50% + 1px));} '+r+':not(.bars) > span::after {top:calc(anchor(var(--undertow-spark-self) bottom) - 1px);bottom:calc(anchor(var(--undertow-spark-prev) bottom) - 1px);background:linear-gradient(to bottom right,transparent calc(50% - 1px),var(--undertow-spark-color) calc(50% - 1px),var(--undertow-spark-color) calc(50% + 1px),transparent calc(50% + 1px));} '+r+':not(.bars) > span:first-child::before,'+r+':not(.bars) > span:first-child::after {content:none;}'
for i in range(1,25):s+=r+f' > span:nth-child({i}) {{--undertow-spark-self:--undertow-spark-{i};--undertow-spark-prev:--undertow-spark-{i-1};}}'
add('sparkline',s)
r='.slope[data-el="undertow-slope"]:not(.dumbbell)';s=r+' {display:block;padding:var(--gap-lg) 0;isolation:isolate;} '+r+' .heads {position:absolute;top:0;left:28%;right:6%;} '+r+' .pair {position:static;padding:0;border:0;min-height:0;} '+r+' .pair .name {position:absolute;left:0;top:calc(var(--gap-lg)*2 + var(--undertow-slope-index)*var(--gap-lg));width:22%;font-size:var(--type-16);} '+r+' .pair .a {position:absolute;left:28%;top:calc(14% + (1 - var(--a)/var(--max))*72%);bottom:auto;transform:translate(-100%,-100%);font-size:var(--type-14);line-height:var(--label-line);} '+r+' .pair .b {position:absolute;left:94%;top:calc(14% + (1 - var(--b)/var(--max))*72%);bottom:auto;transform:translate(0,-100%);font-size:var(--type-14);line-height:var(--label-line);} '+r+' .pair::before {position:absolute;left:28%;top:calc(14% + (1 - var(--a)/var(--max))*72%);--undertow-slope-dy:calc((var(--a) - var(--b))/var(--max)*72cqh);width:hypot(66cqw,var(--undertow-slope-dy));height:1px;border:0;background:var(--n-4);transform:rotate(atan2(var(--undertow-slope-dy),66cqw));transform-origin:left;z-index:-1;} '+r+' .pair.on::before {background:var(--a1);} @container (max-width:700px) {'+r+' .pair .a,'+r+' .pair .b {font-size:var(--type-10);} '+r+' .pair .name {font-size:var(--type-12);}}'
for i in range(1,9):s+=r+f' .pair:nth-child({i} of .pair) {{--undertow-slope-index:{i-1};}}'
add('slope',s)
p=C/'slope/fixtures/slope-5.html';p.write_text(p.read_text().replace('min: 6x4','min: 6x5'))
